import{_ as t,o as a,c as s,ag as d}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"Modules","description":"Every module a game can reach, spelled the way a game writes it, each linking to its page","frontmatter":{"description":"Every module a game can reach, spelled the way a game writes it, each linking to its page","outline":[2,2]},"headers":[],"relativePath":"modules/index.md","filePath":"modules/index.md"}'),o={name:"modules/index.md"};function r(i,e,n,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[d('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /modules.md for this page in Markdown format</div><h1 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h1><p>Every name below is a field on <code>tecs</code>, spelled here exactly as a game writes it. <code>tecs</code> is ambient in a game: the module installs itself as a global as it returns and the host has already loaded it by the time an entry file runs, so no file in a game needs a require line. A headless tool or a spec does not go through the host and writes <code>local tecs &lt;const&gt; = require(&quot;tecs&quot;)</code> first; it is the same table either way.</p><p>Each module is one namespace, and the thing inside it carries its own name: <code>tecs.gfx.Camera</code> is the class, <code>tecs.gfx</code> is where it lives. So no name is a type and a namespace at once, and a satellite record sits beside the class rather than under it -- <code>tecs.window.Options</code>, not <code>tecs.window.Window.Options</code>.</p><p>A module may also sit inside another module, one level and no deeper: <code>tecs.gfx.layers</code> is a module, and there is no third namespace under it. A subordinate module is listed here under its own full name and has a page of its own, because it is a module rather than a section of its parent; a type its parent owns stays on the parent&#39;s page.</p><p>The list is alphabetical, ignoring case, because that is how a name is looked up. A reader arrives holding <code>tecs.filesystem.watch</code> and wants the line that says <code>tecs.filesystem.watch</code>, not a category somebody else chose to file it under. A subordinate module sorts directly after its parent, since that is where its full name puts it.</p><p>This list is the index; the pages behind it are the reference. For signatures, parameters and returns of everything at once, see <a href="/modules/">the generated reference</a>, which is rendered from <code>src/tecs/init.tl</code> and checked against a fresh render so it cannot drift.</p><h2 id="every-module" tabindex="-1">Every module <a class="header-anchor" href="#every-module" aria-label="Permalink to &quot;Every module&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>What it is</th></tr></thead><tbody><tr><td><a href="/modules/application.html"><code>tecs.application</code></a></td><td>the object an entry file returns, and what builds one</td></tr><tr><td><a href="/modules/assets.html"><code>tecs.assets</code></a></td><td>loading content, cached and off the main thread</td></tr><tr><td><a href="/modules/audio.html"><code>tecs.audio</code></a></td><td>clips, voices, groups, limits, the <code>Sound</code> component, and devices</td></tr><tr><td><a href="/modules/box2d.html"><code>tecs.box2d</code></a></td><td>rigid-body simulation on Box2D 3</td></tr><tr><td><a href="/modules/data.html"><code>tecs.data</code></a></td><td>JSON, DEFLATE and hashes over byte strings</td></tr><tr><td><a href="/ecs/"><code>tecs.ecs</code></a></td><td>worlds, components, queries, systems, events and resources</td></tr><tr><td><a href="/modules/events.html"><code>tecs.events</code></a></td><td>platform events, typed once and routed</td></tr><tr><td><a href="/modules/filesystem/"><code>tecs.filesystem</code></a></td><td>where a game may read and write, and what to do with a path</td></tr><tr><td><a href="/modules/filesystem/watch.html"><code>tecs.filesystem.watch</code></a></td><td>watching files for change</td></tr><tr><td><a href="/modules/future.html"><code>tecs.future</code></a></td><td>a value that settles once</td></tr><tr><td><a href="/modules/gfx/"><code>tecs.gfx</code></a></td><td>the camera, the components, the renderer, text, and the vocabularies below</td></tr><tr><td><a href="/modules/gfx/animation.html"><code>tecs.gfx.animation</code></a></td><td>sprite sheets, and the playback that reads them</td></tr><tr><td><a href="/modules/gfx/layers.html"><code>tecs.gfx.layers</code></a></td><td>z-ordering and per-layer behaviour</td></tr><tr><td><a href="/modules/gfx/materials.html"><code>tecs.gfx.materials</code></a></td><td>the material a draw dispatches to</td></tr><tr><td><a href="/modules/gfx/particles.html"><code>tecs.gfx.particles</code></a></td><td>emitters</td></tr><tr><td><a href="/modules/input.html"><code>tecs.input</code></a></td><td>gameplay input, the gamepads on it, and standalone sensors</td></tr><tr><td><a href="/modules/log.html"><code>tecs.log</code></a></td><td>SDL&#39;s logging, per platform, with a named logger as the unit of filtering</td></tr><tr><td><a href="/modules/mcp.html"><code>tecs.mcp</code></a></td><td>the debug server: transport, tools, sandbox</td></tr><tr><td><a href="/modules/net/"><code>tecs.net</code></a></td><td>nonblocking TCP streams and UDP datagrams</td></tr><tr><td><a href="/modules/net/http.html"><code>tecs.net.http</code></a></td><td>fetching over HTTP without stopping the frame</td></tr><tr><td><a href="/modules/sequence.html"><code>tecs.sequence</code></a></td><td>the sequencer, with the tween runtime inside it</td></tr><tr><td><a href="/modules/system.html"><code>tecs.system</code></a></td><td>capabilities, the clipboard, child processes, and what the desktop offers</td></tr><tr><td><a href="/modules/time.html"><code>tecs.time</code></a></td><td>monotonic time</td></tr><tr><td><a href="/ecs/builtins.html#transform"><code>tecs.Transform</code></a></td><td>where an entity is, and the one component every subsystem moves</td></tr><tr><td><a href="/modules/"><code>tecs.version</code></a></td><td>the version of this build, as a string</td></tr><tr><td><a href="/modules/window.html"><code>tecs.window</code></a></td><td>the window, its size, its display and its mode</td></tr><tr><td><a href="/modules/workers.html"><code>tecs.workers</code></a></td><td>typed background jobs</td></tr></tbody></table><h2 id="tecs-ecs" tabindex="-1">tecs.ecs <a class="header-anchor" href="#tecs-ecs" aria-label="Permalink to &quot;tecs.ecs&quot;">​</a></h2><p><code>tecs.ecs</code> is the ECS: <code>tecs.ecs.newWorld</code>, <code>tecs.Transform</code>, <code>tecs.ecs.phases</code>, <code>tecs.ecs.runif</code>, <code>tecs.ecs.random</code> and the component constructors. It is one table with two ways in. A game reads it off <code>tecs</code> like any other module; an engine module writes <code>require(&quot;tecs.ecs&quot;)</code>, because <code>tecs</code> is the aggregator that pulls every engine module in and a module <code>tecs</code> exports cannot also depend on <code>tecs</code> without making a cycle, which Teal rejects even through a type-only require. Both spellings reach the same table.</p><p>What follows are the concepts behind those names, which are pages rather than names.</p><ul><li><a href="/ecs/">Overview</a> -- the model, in one page</li><li><a href="/ecs/archetype.html">Archetypes</a> -- cache-friendly storage for millions of entities</li><li><a href="/ecs/builtins.html">Builtins</a> -- names, transforms, hierarchy, TTL, pause, disable, state events</li><li><a href="/ecs/components/bundles.html">Bundles</a> -- reusable entity templates and batch spawning</li><li><a href="/ecs/components/">Components</a> -- table, tag, scalar and FFI data containers</li><li><a href="/ecs/components/dirty-tracking.html">Dirty tracking</a> -- change-gated systems and GPU synchronisation</li><li><a href="/ecs/events.html">Events</a> -- type-safe pub/sub and entity lifecycle events</li><li><a href="/ecs/mutation-model.html">Mutation model</a> -- the normative rules for reads, writes and dirty bits</li><li><a href="/ecs/phases.html">Phases</a> -- ordered phase scheduling</li><li><a href="/ecs/plugins.html">Plugins</a> -- modular, shareable game mechanics</li><li><a href="/ecs/profiling.html">Profiling</a> -- where a frame went</li><li><a href="/ecs/queries/">Queries</a> -- reusable filters with archetype iteration, callbacks and grouping</li><li><a href="/ecs/random.html">Random</a> -- seeded generation, in named streams a snapshot carries</li><li><a href="/ecs/relationships/">Relationships</a> -- links, hierarchies, relative transforms, cascade deletion</li><li><a href="/ecs/save-games.html">Save games</a> -- snapshots, component codecs, migrations, resource handlers</li><li><a href="/ecs/states.html">States</a> -- stack-based game states with transition events</li><li><a href="/ecs/systems.html">Systems</a> -- phase scheduling, dependencies and run conditions</li><li><a href="/ecs/world.html">World</a> -- entities, resources and the state stack</li></ul><h2 id="what-loads-when" tabindex="-1">What loads when <a class="header-anchor" href="#what-loads-when" aria-label="Permalink to &quot;What loads when&quot;">​</a></h2><p><code>tecs.ecs</code> loads with <code>tecs</code>, because it reaches nothing below Lua. Every other module is named on <code>tecs</code> for its types and resolved on first field access, because each of them reaches SDL, Box2D or a worker library through the FFI, and loading them up front would make a test, a server or a tool demand a graphics stack it never asked for. Reading <code>tecs.gfx</code> loads it; requiring <code>tecs</code> does not.</p><p>A name that is not a module answers nil rather than raising, and the modules are written out in <code>init.tl</code> rather than derived from a module path, so <code>tecs.cmaera</code> is nil where it is written instead of an error out of <code>require</code> about a module nobody meant to ask for.</p><p>Nothing else is supported, with one exception: the <code>tecs.utils.*</code> modules (<code>profile</code>, <code>pool</code>, <code>Bitset</code>) may be required directly. <code>tecs.internal.*</code> modules are implementation details with no stability guarantee.</p>',17)])])}const p=t(o,[["render",r]]);export{u as __pageData,p as default};
